// A function to look up a value in a container and return it.
// Needs to return a reference to allow modification.
template<typename Container, typename Index>
decltype(auto) access(Container&& c, Index i)
{
  return std::forward<Container>(c)[i];
}

// C++11 equivalent for the same behavior
template<typename Container, typename Index>
auto access_cpp11(Container&& c, Index i)
  -> decltype(std::forward<Container>(c)[i])
{
  return std::forward<Container>(c)[i];
}
